	public toggleView(isTopView) {
		this.isTopView = isTopView;

		if (this.isTopView) {
			// Top view - orthographic-like perspective
			this.camera.position.set(0, 50, 0);
			this.camera.setFocalLength(100);
			this.camera.lookAt(0, 0, 0);
			if (this.controls) {
				this.controls.enabled = false;
			}
		} else {
			// Perspective view
			this.camera.position.set(8, 8, 8);
			this.camera.lookAt(0, 0, 0);
			this.camera.setFocalLength(28);
			if (this.controls) {
				this.controls.enabled = true;
			}
		}
	}

	private createHoverBox(x, z) {
		if (this.hoverBox) {
			this.scene.remove(this.hoverBox);
			this.hoverBox.geometry.dispose();
			this.hoverBox.material.dispose();
		}

		const geometry = new THREE.BoxGeometry(this.cellSize * 0.98, 0.1, this.cellSize * 0.98);
		const material = new THREE.MeshBasicMaterial({
			color: 0x00ff00,
			transparent: true,
			opacity: 0.3,
		});
		this.hoverBox = new THREE.Mesh(geometry, material);

		const worldX = x - this.gridSize / 2 + 0.5;
		const worldZ = z - this.gridSize / 2 + 0.5;

		this.hoverBox.position.set(worldX, 0.05, worldZ);
		this.scene.add(this.hoverBox);
	}

	private removeHoverBox() {
		if (this.hoverBox) {
			this.scene.remove(this.hoverBox);
			this.hoverBox.geometry.dispose();
			this.hoverBox.material.dispose();
			this.hoverBox = null;
		}
		this.hoveredGridCell = null;
	}

